def search_all(query):
    all_res=[]
    page_index=0
    while True:
        res = apis.amazon.search_products(query=query, page_index=page_index, page_limit=20, sort_by=None)
        if not res:
            break
        all_res.extend(res)
        page_index += 1
        if page_index>50:
            break
    return all_res

